'use client';
import { useFrame } from '@react-three/fiber';
import { useEffect, useRef } from 'react';
import type * as THREE from 'three';
import { Asset } from '@/components/three/AssetLoader';
import { GenerationSlice } from '@/components/three/GenerationSlice';
import { ModelStage } from '@/components/three/ModelStage';
import { usePerfStore } from '@/lib/perf';

const CYCLE = 9; // seconds
const START = 0.6;
const SWEEP = 3.2;

/** Looping hero: the dog is generated by the slice, holds, then regenerates. */
function GeneratingDog({ onStatus }: { onStatus: (done: boolean) => void }) {
  const ref = useRef<THREE.Group>(null);
  const progress = useRef(0);
  const reduced = usePerfStore((s) => s.reducedMotion);
  const last = useRef<boolean | null>(null);

  useFrame(({ clock }) => {
    if (reduced) {
      progress.current = 1;
    } else {
      const t = clock.elapsedTime % CYCLE;
      const x = Math.min(Math.max((t - START) / SWEEP, 0), 1);
      progress.current = x < 1 ? 1 - Math.pow(1 - x, 2.2) : 1;
    }
    const done = progress.current >= 1;
    if (done !== last.current) {
      last.current = done;
      onStatus(done);
    }
  });

  return (
    <>
      <Asset ref={ref} id="dog" scale={1.15} />
      <GenerationSlice target={ref} progress={progress} />
    </>
  );
}

export default function HeroScene({
  label,
  onStatus,
}: {
  label: string;
  onStatus: (done: boolean) => void;
}) {
  const init = usePerfStore((s) => s.init);
  useEffect(() => init(), [init]);
  return (
    <ModelStage
      className="absolute inset-0"
      camera={[3.1, 1.9, 4.1]}
      target={[0, 0.75, 0]}
      floorRadius={1.4}
      autoRotate
      label={label}
    >
      <GeneratingDog onStatus={onStatus} />
    </ModelStage>
  );
}
